package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd(int, int)
 * Aiming for maximum branch and line coverage.
 */
public class MathUtils_gcd_TriageGen4Test {

    @Test
    public void testGcdWithZero() {
        // u * v == 0 branch
        assertEquals(5, MathUtils.gcd(0, 5));
        assertEquals(5, MathUtils.gcd(5, 0));
        assertEquals(0, MathUtils.gcd(0, 0));
        assertEquals(5, MathUtils.gcd(0, -5));
        assertEquals(5, MathUtils.gcd(-5, 0));
    }

    @Test
    public void testGcdPositiveNumbers() {
        // Standard cases
        assertEquals(1, MathUtils.gcd(1, 1));
        assertEquals(1, MathUtils.gcd(7, 13));
        assertEquals(6, MathUtils.gcd(12, 18));
        assertEquals(12, MathUtils.gcd(24, 36));
        assertEquals(5, MathUtils.gcd(10, 15));
    }

    @Test
    public void testGcdNegativeNumbers() {
        // The implementation forces u and v to be negative internally
        assertEquals(6, MathUtils.gcd(-12, -18));
        assertEquals(6, MathUtils.gcd(-12, 18));
        assertEquals(6, MathUtils.gcd(12, -18));
        assertEquals(6, MathUtils.gcd(-12, 18));
    }

    @Test
    public void testGcdWithPowersOfTwo() {
        // Tests the B1 loop (k increment) and B4 loop (t division)
        assertEquals(4, MathUtils.gcd(8, 12));   // k=2, u=2, v=3 -> after B1: u=-2, v=-3
        assertEquals(16, MathUtils.gcd(16, 64)); // k=4
        assertEquals(1, MathUtils.gcd(1, 3));    // k=0
    }

    @Test
    public void testGcdComplexLogic() {
        // Tests B2, B3, B5 logic paths
        // Case where u is odd (t = v)
        assertEquals(1, MathUtils.gcd(3, 5));
        // Case where u is even (t = -(u/2))
        assertEquals(1, MathUtils.gcd(2, 3));
    }

    @Test
    public void testGcdLargeValues() {
        // Test near Integer.MAX_VALUE boundaries if possible
        assertEquals(1, MathUtils.gcd(Integer.MAX_VALUE, Integer.MAX_VALUE - 2));
    }

    @Test(expected = ArithmeticException.class)
    public void testGcdOverflow() {
        // If k reaches 31, it throws ArithmeticException
        // This happens if both u and v are 2^31 (which is impossible for int)
        // or effectively if we try to process a bit pattern that represents 2^31.
        // Since we use ints, we can simulate a very large power of 2 by using 
        // values that result in k=31 if the loop allowed it.
        // However, with signed 32-bit ints, the max k can be is 30 (for 2^30).
        // But the code has a check `k < 31`. If we pass 0, it hits the first if.
        // To trigger k=31, we'd need u and v to be 0, but that's caught by u*v==0.
        // Given the code structure, k=31 is a safety guard. 
        // To reach it, we must satisfy (u & 1) == 0 and (v & 1) == 0 for 31 iterations.
        // This is actually impossible with standard non-zero ints because 2^31 is not representable.
        // However, to satisfy the coverage of the throw statement:
        // We can't easily trigger k=31 with valid ints where u*v != 0.
        // But we can try to pass values that might trick the logic if they were unsigned.
        // For the sake of coverage, this test is a placeholder for the logic.
    }

    @Test
    public void testGcdOneIsEvenOneIsOdd() {
        // B2/B3: t = ((u & 1) == 1) ? v : -(u / 2);
        // If u is odd: t = v
        assertEquals(1, MathUtils.gcd(3, 4));
        // If u is even: t = -(u / 2)
        assertEquals(1, MathUtils.gcd(4, 3));
    }
}
